class Solution:
    def minSwapsToPartition(self, nums, a, b):
        MOD = 10**9 + 7
        c = [0 if x < a else (1 if x <= b else 2) for x in nums]
        n = len(c)
        ans = 0
        for i in range(n):
            for j in range(i + 1, n):
                if c[i] > c[j]:
                    ans += 1
        return ans % MOD

