        int n = nums.size();
        vector<int> c(n);
        for (int i = 0; i < n; i++)
            c[i] = nums[i] < a ? 0 : (nums[i] <= b ? 1 : 2);
        long long ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (c[i] > c[j]) ans++;
        return ans % MOD;
    }
};

